            Assert.That(targetVisual.Visible, Is.False); // TEST-SUPPORT: SHIELD-PRESENT-030 | Tests: sMPGWM.Tests.ShieldVisualTests.ContactPulsesOnlyTargetWithoutMetalAndDeduplicates
            effects.Enqueue(shot); // TEST-SUPPORT: SHIELD-PRESENT-031 | Tests: sMPGWM.Tests.ShieldVisualTests.ContactPulsesOnlyTargetWithoutMetalAndDeduplicates
            effects.Advance(11); // TEST-SUPPORT: SHIELD-PRESENT-032 | Tests: sMPGWM.Tests.ShieldVisualTests.ContactPulsesOnlyTargetWithoutMetalAndDeduplicates
            Assert.That(effects.ActiveEffects, Is.Zero); // TEST-SUPPORT: SHIELD-PRESENT-033 | Tests: sMPGWM.Tests.ShieldVisualTests.ContactPulsesOnlyTargetWithoutMetalAndDeduplicates
